def partition(arr: list[int]) -> list[int]:
    pivot = arr[0]
    i = 0
    for j in range(1, len(arr)):
        if arr[j] < pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[0], arr[i] = arr[i], arr[0]
    return arr

